// PROBE_ARRAY_MAX_BITS is the longest wire path; align pads at worst case (SPEC §6.1).
// PROBE_ARRAY_MAX_BYTES is rounded up to the 8-byte write-buffer granularity.
pub const PROBE_ARRAY_MAX_BITS: u64 = 588;
pub const PROBE_ARRAY_MAX_BYTES: usize = 80;

#[inline(always)]
pub fn write_probe_array(stream: &mut WriteStream<'_>, value: &ProbeArray) -> Result {
    for i in 0..2 {
        write_probe_sample(stream, &value.samples[i])?;
    }
    write_probe_config(stream, &value.config)?;
    Ok(())
}

#[inline]
pub fn read_probe_array(stream: &mut ReadStream<'_>, value: &mut ProbeArray) -> Result {
    for i in 0..2 {
        read_probe_sample(stream, &mut value.samples[i])?;
    }
    read_probe_config(stream, &mut value.config)?;
    Ok(())
}

// type ProbeReport
#[repr(C)]
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct ProbeReport {
    pub header: ProbeHeader,
    pub flags: ProbeFlags,
    pub echo: Test,
}

// The zero form (SPEC §5): specified defaults live only in new(), never here.
impl Default for ProbeReport {
    fn default() -> Self {
        ProbeReport {
            header: ProbeHeader::default(),
            flags: 0,
            echo: Test::default(),
        }
    }
}

// PROBE_REPORT_MAX_BITS is the longest wire path; align pads at worst case (SPEC §6.1).
// PROBE_REPORT_MAX_BYTES is rounded up to the 8-byte write-buffer granularity.
pub const PROBE_REPORT_MAX_BITS: u64 = 141;
pub const PROBE_REPORT_MAX_BYTES: usize = 24;

#[inline(always)]
pub fn write_probe_report(stream: &mut WriteStream<'_>, value: &ProbeReport) -> Result {
    write_probe_header(stream, &value.header)?;
    if value.flags >= 1 << 8 {
        // a mask bit above the wire width cannot ride
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut flags_value = value.flags as u32;
        stream.serialize_bits(&mut flags_value, 8)?;
    }
    write_test(stream, &value.echo)?;
    Ok(())
}

#[inline]
pub fn read_probe_report(stream: &mut ReadStream<'_>, value: &mut ProbeReport) -> Result {
    read_probe_header(stream, &mut value.header)?;
    {
        let mut flags_value: u32 = 0;
        stream.serialize_bits(&mut flags_value, 8)?;
        value.flags = flags_value as ProbeFlags;
    }
    read_test(stream, &mut value.echo)?;
    Ok(())
}

// type TestData
#[repr(C)]
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct TestData {
    pub a: i32, // wire [-100, 100]
    pub b: i32, // wire [-100, 100]
    pub c: i32, // wire [-100, 150]
    pub d: u32,
    pub e: u32,
    pub f: u32,
    pub g: bool,
    pub items: [i32; 16], // used count beside it; wire count in [0, 16]
    pub items_count: i32,
    pub float_value: f32,
    pub compressed_float_value: f32, // compressed float [0.0, 10.0] @ 0.01
    pub double_value: f64,
    pub int8_value: i8,
    pub int16_value: i16,
    pub uint8_value: u8,
    pub uint16_value: u16,
    pub uint32_value: u32,
    pub uint64_value: u64,
    pub int64_full: i64,
    pub int64_range: i64, // wire [-1000000000000, 1000000000000]
    pub fixed_bytes: [u8; 17],
    pub text: [u8; 255], // string(255): max length, used length beside it (SPEC §4.7)
    pub text_length: i32,
}

// The zero form (SPEC §5): specified defaults live only in new(), never here.
impl Default for TestData {
    fn default() -> Self {
        TestData {
            a: 0,
            b: 0,
            c: 0,
            d: 0,
            e: 0,
            f: 0,
            g: false,
            items: [0; 16],
            items_count: 0,
            float_value: 0.0,
            compressed_float_value: 0.0,
            double_value: 0.0,
            int8_value: 0,
            int16_value: 0,
            uint8_value: 0,
            uint16_value: 0,
            uint32_value: 0,
            uint64_value: 0,
            int64_full: 0,
            int64_range: 0,
            fixed_bytes: [0; 17],
            text: [0; 255],
            text_length: 0,
        }
    }
}

// TEST_DATA_MAX_BITS is the longest wire path; align pads at worst case (SPEC §6.1).
// TEST_DATA_MAX_BYTES is rounded up to the 8-byte write-buffer granularity.
pub const TEST_DATA_MAX_BITS: u64 = 2735;
pub const TEST_DATA_MAX_BYTES: usize = 344;

#[inline(always)]
pub fn write_test_data(stream: &mut WriteStream<'_>, value: &TestData) -> Result {
    if value.a < -100 || value.a > 100 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut offset_value = (value.a as u32).wrapping_sub((-100_i32) as u32);
        stream.serialize_bits(&mut offset_value, 8)?;
    }
    if value.b < -100 || value.b > 100 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut offset_value = (value.b as u32).wrapping_sub((-100_i32) as u32);
        stream.serialize_bits(&mut offset_value, 8)?;
    }
    if value.c < -100 || value.c > 150 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut offset_value = (value.c as u32).wrapping_sub((-100_i32) as u32);
        stream.serialize_bits(&mut offset_value, 8)?;
    }
    if value.d >= 1 << 8 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut raw_value = value.d;
        stream.serialize_bits(&mut raw_value, 8)?;
    }
    if value.e >= 1 << 8 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut raw_value = value.e;
        stream.serialize_bits(&mut raw_value, 8)?;
    }
    if value.f >= 1 << 8 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut raw_value = value.f;
        stream.serialize_bits(&mut raw_value, 8)?;
    }
    {
        let mut bool_value = value.g;
        stream.serialize_bool(&mut bool_value)?;
    }
    if value.items_count < 0 || value.items_count > 16 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut offset_value = value.items_count as u32;
        stream.serialize_bits(&mut offset_value, 5)?; // the count guards the loop (§6.3)
    }
    for i in 0..value.items_count as usize {
        if value.items[i] < 0 || value.items[i] > 255 {
            return Err(Error::Stream(serialize::Error::ValueOutOfRange));
        }
        {
            let mut offset_value = value.items[i] as u32;
            stream.serialize_bits(&mut offset_value, 8)?;
        }
    }
    {
        let mut float_value = value.float_value;
        stream.serialize_f32(&mut float_value)?;
    }
    {
        let mut compressed_value = value.compressed_float_value;
        stream.serialize_compressed_float_precomputed(&mut compressed_value, 1000, 10, 10.0_f32, 0.0_f32)?; // compressed float [0.0, 10.0] @ 0.01, constants folded at generation
    }
    {
        let mut float_value = value.double_value;
        stream.serialize_f64(&mut float_value)?;
    }
    {
        let mut raw_value = (value.int8_value as u8) as u32;
        stream.serialize_bits(&mut raw_value, 8)?;
    }
    {
        let mut raw_value = (value.int16_value as u16) as u32;
        stream.serialize_bits(&mut raw_value, 16)?;
    }
    {
        let mut raw_value = value.uint8_value as u32;
        stream.serialize_bits(&mut raw_value, 8)?;
    }
    {
        let mut raw_value = value.uint16_value as u32;
        stream.serialize_bits(&mut raw_value, 16)?;
    }
    {
        let mut raw_value = value.uint32_value;
        stream.serialize_bits(&mut raw_value, 32)?;
    }
    {
        let mut raw_value = value.uint64_value;
        stream.serialize_bits64(&mut raw_value, 64)?;
    }
    {
        let mut raw_value = value.int64_full as u64;
        stream.serialize_bits64(&mut raw_value, 64)?;
    }
    if value.int64_range < -1000000000000 || value.int64_range > 1000000000000 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    {
        let mut offset_value = (value.int64_range as u64).wrapping_sub((-1000000000000_i64) as u64);
        stream.serialize_bits64(&mut offset_value, 41)?;
    }
    stream.serialize_align()?;
    stream.write_bytes(&value.fixed_bytes); // byte-aligned [N]u8 — bulk copy, wire-identical to the per-byte loop (infallible: returns () in serialize.rs 2.0.0)
    if value.text_length < 0 || value.text_length > 255 {
        return Err(Error::Stream(serialize::Error::ValueOutOfRange));
    }
    debug_assert!(
        std::str::from_utf8(&value.text[..value.text_length as usize]).is_ok(),
        "string(N) payloads are well-formed UTF-8 by contract (SPEC 4.7)"
    );
    {
        let mut offset_value = value.text_length as u32;
        stream.serialize_bits(&mut offset_value, 8)?; // the length guards the slice (§6.3)
    }
    stream.write_bytes(&value.text[..value.text_length as usize]); // borrowed in place: the write side never mutates (infallible: returns () in serialize.rs 2.0.0)
    Ok(())
}

#[inline]
pub fn read_test_data(stream: &mut ReadStream<'_>, value: &mut TestData) -> Result {
    stream.serialize_int(&mut value.a, -100, 100)?;
    stream.serialize_int(&mut value.b, -100, 100)?;
    stream.serialize_int(&mut value.c, -100, 150)?;
    stream.serialize_bits(&mut value.d, 8)?;
    stream.serialize_bits(&mut value.e, 8)?;
    stream.serialize_bits(&mut value.f, 8)?;
    stream.serialize_bool(&mut value.g)?;
    stream.serialize_int(&mut value.items_count, 0, 16)?; // the count guards the loop (§6.3)
    for i in 0..value.items_count as usize {
        stream.serialize_int(&mut value.items[i], 0, 255)?;
    }
    stream.serialize_f32(&mut value.float_value)?;
    stream.serialize_compressed_float_precomputed(&mut value.compressed_float_value, 1000, 10, 10.0_f32, 0.0_f32)?; // compressed float [0.0, 10.0] @ 0.01, constants folded at generation
    stream.serialize_f64(&mut value.double_value)?;
    {
        let mut raw_value: u32 = 0;
        stream.serialize_bits(&mut raw_value, 8)?;
        value.int8_value = raw_value as u8 as i8;
    }
    {
        let mut raw_value: u32 = 0;
        stream.serialize_bits(&mut raw_value, 16)?;
        value.int16_value = raw_value as u16 as i16;
    }
    {
        let mut raw_value: u32 = 0;
        stream.serialize_bits(&mut raw_value, 8)?;
        value.uint8_value = raw_value as u8;
    }
    {
        let mut raw_value: u32 = 0;
        stream.serialize_bits(&mut raw_value, 16)?;
        value.uint16_value = raw_value as u16;
    }
    stream.serialize_bits(&mut value.uint32_value, 32)?;
    stream.serialize_bits64(&mut value.uint64_value, 64)?;
    {
        let mut raw_value: u64 = 0;
        stream.serialize_bits64(&mut raw_value, 64)?;
        value.int64_full = raw_value as i64;
    }
    stream.serialize_int64(&mut value.int64_range, -1000000000000, 1000000000000)?;
    stream.serialize_align()?; // rejects nonzero padding (SPEC §4.3)
    stream.serialize_bytes(&mut value.fixed_bytes)?; // byte-aligned [N]u8 — bulk copy, wire-identical to the per-byte loop
    stream.serialize_int(&mut value.text_length, 0, 255)?; // the length guards the slice (§6.3)
    stream.serialize_bytes(&mut value.text[..value.text_length as usize])?;
    for i in 0..value.text_length as usize {
        if value.text[i] == 0 {
            return Err(Error::Validation);
        }
    }
    Ok(())
}

// type CompressedProbe
#[repr(C)]
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct CompressedProbe {
    pub boundary: f32, // compressed float [0.0, 10.0] @ 0.01
    pub offset: f32, // compressed float [-5.0, 5.0] @ 0.001
}

// The zero form (SPEC §5): specified defaults live only in new(), never here.
impl Default for CompressedProbe {
    fn default() -> Self {
        CompressedProbe {
            boundary: 0.0,
            offset: 0.0,
        }
    }
}

// COMPRESSED_PROBE_MAX_BITS is the longest wire path; align pads at worst case (SPEC §6.1).
// COMPRESSED_PROBE_MAX_BYTES is rounded up to the 8-byte write-buffer granularity.
pub const COMPRESSED_PROBE_MAX_BITS: u64 = 24;
pub const COMPRESSED_PROBE_MAX_BYTES: usize = 8;

#[inline(always)]
pub fn write_compressed_probe(stream: &mut WriteStream<'_>, value: &CompressedProbe) -> Result {
    {
        let mut compressed_value = value.boundary;
        stream.serialize_compressed_float_precomputed(&mut compressed_value, 1000, 10, 10.0_f32, 0.0_f32)?; // compressed float [0.0, 10.0] @ 0.01, constants folded at generation
    }
    {
        let mut compressed_value = value.offset;
        stream.serialize_compressed_float_precomputed(&mut compressed_value, 10000, 14, 10.0_f32, -5.0_f32)?; // compressed float [-5.0, 5.0] @ 0.001, constants folded at generation
    }
    Ok(())
}

#[inline]
pub fn read_compressed_probe(stream: &mut ReadStream<'_>, value: &mut CompressedProbe) -> Result {
    stream.serialize_compressed_float_precomputed(&mut value.boundary, 1000, 10, 10.0_f32, 0.0_f32)?; // compressed float [0.0, 10.0] @ 0.01, constants folded at generation
    stream.serialize_compressed_float_precomputed(&mut value.offset, 10000, 14, 10.0_f32, -5.0_f32)?; // compressed float [-5.0, 5.0] @ 0.001, constants folded at generation
    Ok(())
}

